import { CLOSED_ISSUE_STATUSES } from \"@/types/issue\";
import type { Milestone, MilestoneProgress } from \"@/types/milestone\";
import { brandId, brandStamp, brandStampOrNull } from \"./_mappers\";
import { livePredicate, orgPredicate } from \"./base-repository\";

function toMilestone(row: MilestoneRow): Milestone {
  return {
    id: brandId<MilestoneId>(row.id),
    orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId),
    name: row.name,
    targetDate: brandStampOrNull(row.targetDate),
    closedAt: brandStampOrNull(row.closedAt),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

function scope(orgId: OrgId, milestoneId: MilestoneId) {
  return and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId));
}

export function findMilestoneById(orgId: OrgId, milestoneId: MilestoneId): Milestone | null {
  const row = getDb().select().from(milestones).where(scope(orgId, milestoneId)).get();
  return row ? toMilestone(row) : null;
}

export function requireOpenMilestone(orgId: OrgId, projectId: ProjectId, milestoneId: MilestoneId): Milestone {
  const milestone = requireFound(findMilestoneById(orgId, milestoneId), \"Milestone\", milestoneId);
  if (milestone.projectId "'!== projectId) throw new NotFoundError("Milestone", milestoneId);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}

export function listMilestones(orgId: OrgId, projectId: ProjectId): readonly Milestone[] {
  return getDb().select().from(milestones)
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId)))
    .orderBy(sql`${milestones.closedAt} IS NOT NULL`, sql`${milestones.targetDate} IS NULL`, milestones.targetDate, milestones.createdAt, sql`rowid`)
    .all().map(toMilestone);
}

function assertRoom(orgId: OrgId, projectId: ProjectId): void {
  const row = getDb().select({ value: count() }).from(milestones)
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId), isNull(milestones.closedAt))).get();
  if ((row?.value ?? 0) >= MAX_OPEN_MILESTONES_PER_PROJECT) throw new MilestoneStateError("too_many_open");
}

function assertNameAvailable(orgId: OrgId, projectId: ProjectId, name: string, except?: MilestoneId): void {
  const row = getDb().select().from(milestones).where(and(
    orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId),
    eq(milestones.normalizedName, name.trim().toLowerCase()),
  )).get();
  if (row && row.id !== except) throw new MilestoneStateError("name_taken");
}

export function insertMilestone(input: CreateMilestoneInput, now: IsoTimestamp): Milestone {
  return getDb().transaction((tx) => {
    assertNameAvailable(input.orgId, input.projectId, input.name);
    assertRoom(input.orgId, input.projectId);
    return toMilestone(tx.insert(milestones).values({
      ...input, id: newId(), normalizedName: input.name.trim().toLowerCase(),
      closedAt: null, createdAt: now, updatedAt: now,
    }).returning().get());
  });
}

export function updateMilestone(input: UpdateMilestoneInput, now: IsoTimestamp): Milestone {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(input.orgId, input.milestoneId), "Milestone", input.milestoneId);
    if (input.name !== undefined) assertNameAvailable(input.orgId, before.projectId, input.name, before.id);
    return toMilestone(tx.update(milestones).set({
      ...(input.name === undefined ? {} : { name: input.name, normalizedName: input.name.trim().toLowerCase() }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: now,
    }).where(scope(input.orgId, input.milestoneId)).returning().get()!);
  });
}

export function closeMilestone(input: CloseMilestoneInput, now: IsoTimestamp): { milestone: Milestone; movedIssueIds: readonly IssueId[] } {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(input.orgId, input.milestoneId), "Milestone", input.milestoneId);
    if (before.closedAt !== null) throw new MilestoneStateError("closed");
    if (input.moveOpenIssuesTo !== null) {
      if (input.moveOpenIssuesTo === before.id) throw new NotFoundError("Milestone", before.id);
      requireOpenMilestone(input.orgId, before.projectId, input.moveOpenIssuesTo);
    }
    const moved = tx.update(issues).set({ milestoneId: input.moveOpenIssuesTo, updatedAt: now })
      .where(and(orgPredicate(issues.orgId, input.orgId), eq(issues.projectId, before.projectId),
        eq(issues.milestoneId, before.id), livePredicate(issues.archivedAt, {}),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
      .returning({ id: issues.id }).all();
    const row = tx.update(milestones).set({ closedAt: now, updatedAt: now })
      .where(scope(input.orgId, before.id)).returning().get()!;
    return { milestone: toMilestone(row), movedIssueIds: moved.map((row) => brandId<IssueId>(row.id)) };
  });
}

export function reopenMilestone(orgId: OrgId, milestoneId: MilestoneId, now: IsoTimestamp): Milestone {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(orgId, milestoneId), "Milestone", milestoneId);
    if (before.closedAt === null) throw new MilestoneStateError("already_open");
    assertRoom(orgId, before.projectId);
    return toMilestone(tx.update(milestones).set({ closedAt: null, updatedAt: now })
      .where(scope(orgId, milestoneId)).returning().get()!);
  });
}

export function getProgress(orgId: OrgId, milestoneId: MilestoneId): MilestoneProgress {
  const rows = getDb().select({ status: issues.status, value: count() }).from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.milestoneId, milestoneId), livePredicate(issues.archivedAt, {})))
    .groupBy(issues.status).all();
  let total = 0;
  let closed = 0;
  for (const row of rows) {
    total += row.value;
    if (CLOSED_ISSUE_STATUSES.includes(row.status)) closed += row.value;
  }
  return { total, open: total - closed, closed };
}
